export function forwardTrustedFrameError(
  event: MessageEvent,
  frameWindow: Window,
  context: Readonly<{
    surface: Exclude<FrontendErrorSurface, 'workshop'>
    gatekeeperVendorId?: string
  }>,
  forward: BrowserReporter['reportSerialized'] = reporter.reportSerialized,
): boolean {
